class Solution {
    public int sumOddLengthSubarrays(int[] arr) {
        int n = arr.length;
        long sum = 0;
        for (int i = 0; i < n; i++) {
            int leftCount = i + 1;
            int rightCount = n - i;
            int total = leftCount * rightCount;
            int oddCount = (total + 1) / 2;
            sum += (long) arr[i] * oddCount;
        }
        return (int) sum;
    }
}

